illustrative_snippet:
variable "dedicated_tier" {
  type        = string
  description = "Dedicated tier: standard | performance | premium"

  validation {
    condition     = contains(["standard", "performance", "premium"], var.dedicated_tier)
    error_message = "dedicated_tier must be one of: standard, performance, premium."
  }
}

# Cross-field validation via locals + precondition (Terraform >= 1.3)
locals {
  tier_shape_allowed = contains(local.allowed_shapes_by_tier[var.dedicated_tier], var.hardware_shape)
  region_shape_allowed = contains(local.allowed_regions_by_shape[var.hardware_shape], var.region)
}

resource "null_resource" "dedicated_input_validation" {
  lifecycle {
    precondition {
      condition     = local.tier_shape_allowed
      error_message = "hardware_shape '${var.hardware_shape}' is not allowed for tier '${var.dedicated_tier}'."
    }
    precondition {
      condition     = local.region_shape_allowed
      error_message = "hardware_shape '${var.hardware_shape}' is not provisionable in region '${var.region}'."
    }
  }
}
